private theorem frob_zpow (hk : IsRAC (⊥ : IntermediateField k K)) (n : ℤ) :
    (⟨π.frobZPow 1, π.frobZPow_mem_pairAut hk 1⟩ : π.pairAut k) ^ n =
      ⟨π.frobZPow n, π.frobZPow_mem_pairAut hk n⟩

theorem range_codeVec_subset_dcl [IsAlgClosed K] {L : IntermediateField k K}
    {S : Finset (ι → K)}
    (h : ∀ σ : K ≃ₐ[↥L] K,
      S.map (compEmb (σ.restrictScalars k) (σ.restrictScalars k).injective) = S) (d : ℕ) :
    range (codeVec d S) ⊆ dcl L

private theorem aeval_termPolynomial {n : ℕ} (t : Language.ring.Term (Empty ⊕ Fin n))
    (x : Fin n → K) : aeval x (termPolynomial (k := k) t) =
      t.realize (Sum.elim default x)

theorem isConstructibleOver_realize [IsAlgClosed K] {n : ℕ}
    (φ : Language.ring.BoundedFormula Empty n) :
    IsConstructibleOver k {x : Fin n → K | φ.Realize default x}

theorem finite_conjugates {L : IntermediateField k K} {z : μ → K}
    (hz : ∀ i, IsIntegral (↥L) (z i)) :
    (range fun σ : K ≃ₐ[↥L] K ↦ ⇑σ ∘ z).Finite

private theorem subset_racl_of_indepOver {K₀ W X Y : Set K} (he : IndepOver k ∅ K₀ W)
    (hX : X ⊆ W) (hY : Y ⊆ W) (hYfin : Y.Finite) (h : Y ⊆ racl k (K₀ ∪ X)) :
    Y ⊆ racl k X

private theorem idealOf_quotient_generic (Q : Ideal (MvPolynomial ι F)) [Q.IsPrime] :
    idealOf F (fun i ↦ algebraMap (MvPolynomial ι F ⧸ Q) (FractionRing (MvPolynomial ι F ⧸ Q))
      (Ideal.Quotient.mk Q (X i))) = Q

theorem erk_eq_of_locusIdeal_eq_locusIdeal {M : IntermediateField k K} {a b : ι → K}
    (h : locusIdeal (↥M) a = locusIdeal (↥M) b) :
    erk k (M : Set K) (range a) = erk k (M : Set K) (range b)

theorem racl_eq_of_racl_union_eq {A B T : Set K}
    (h : racl (↥K₀) (A ∪ T) = racl (↥K₀) (B ∪ T)) :
    racl (↥(racl k ((K₀ : Set K) ∪ T))) A = racl (↥(racl k ((K₀ : Set K) ∪ T))) B

theorem mem_dclAdjoin_mono' {L : IntermediateField k K} {L' : IntermediateField k' K}
    {u : ι → K} {u' : ι' → K} (h : (L : Set K) ∪ range u ⊆ (L' : Set K) ∪ range u') {x : K}
    (hx : x ∈ dclAdjoin L u) : x ∈ dclAdjoin L' u'

theorem mem_dclAdjoin_congr {L : IntermediateField k K} {L' : IntermediateField k' K}
    (h : (L : Set K) = (L' : Set K)) (u : ι → K) (x : K) :
    x ∈ dclAdjoin L u ↔ x ∈ dclAdjoin L' u

theorem Ideal.map_eq_comap_of_inverse {R S : Type*} [CommRing R] [CommRing S] {ρ : R →+* S}
    {ρ' : S →+* R} (h₁ : ρ'.comp ρ = RingHom.id R) (h₂ : ρ.comp ρ' = RingHom.id S)
    (J : Ideal R) : J.map ρ = J.comap ρ'

theorem indepOver_base_union_iff {C A B E : Set K}
    (hE : IndepOver k ∅ E (C ∪ (A ∪ B))) :
    IndepOver k C A B ↔ IndepOver k (C ∪ E) A B

theorem coefficientExtension_range :
    LinearMap.range (coefficientExtension W F) =
      Submodule.span R {v : 𝓜 → R | v ∈ W ∧ ∀ j, v j ∈ F}

theorem descent [IsAlgClosed k] [IsAlgClosed K] [UniversalDomain k K] [Finite ι] {κ : Type*}
    [Finite κ] {Φ : Set ((ι ⊕ κ) → K)} (hΦ : IsConstructibleOver k Φ) {w : κ → K} {e : ι → K}
    (hind : IndepOver k ∅ (range e) (range w)) (he : Sum.elim e w ∈ Φ) :
    ∃ e₀ : ι → k, Sum.elim (algebraMap k K ∘ e₀) w ∈ Φ

theorem coordPoly_mem_of_mem_map (l : K →ₗ[R] R) {J : Ideal (MvPolynomial ι R)}
    {f : MvPolynomial ι K} (hf : f ∈ J.map (MvPolynomial.map (algebraMap R K))) :
    coordPoly l f ∈ J

theorem mem_map_comap_of_definedOver {I : Ideal (MvPolynomial ι K)} {d : ℕ}
    (h : DefinedOver (degSubspace I d) F) {f : MvPolynomial ι K} (hf : f ∈ I)
    (hfd : f.totalDegree ≤ d) : f ∈ (I.comap (mapF F)).map (mapF F)

theorem idealDefinedOver_of_span {I : Ideal (MvPolynomial ι K)} {S : Set (MvPolynomial ι K)}
    (hS : Ideal.span S = I) {d : ℕ} (hd : ∀ f ∈ S, f.totalDegree ≤ d)
    (h : DefinedOver (degSubspace I d) F) : IdealDefinedOver F I

theorem orbit_eq_of_transcendental {L : IntermediateField k K} {x : K}
    (hx : Transcendental (↥L) x) :
    range (fun σ : K ≃ₐ[↥L] K ↦ σ x) = {x' | Transcendental (↥L) x'}

theorem isGenericOver_self_of_indepOver [IsAlgClosed k] [IsAlgClosed K] [UniversalDomain k K]
    [Finite ι] {M : IntermediateField k K} (hM : IsSmall k (M : Set K)) {a : ι → K}
    (h : IndepOver k ∅ (Set.range a) (M : Set K)) : IsGenericOver M a a

theorem indepOver_biUnion_of_erk_iUnion_eq_sum [Fintype α] {C : Set K} {X : α → Set K}
    (hX : ∀ i, (X i).Finite) (h : erk k C (⋃ i, X i) = ∑ i, erk k C (X i)) {s : Finset α}
    {i₀ : α} (hi₀ : i₀ ∉ s) : IndepOver k C (X i₀) (⋃ i ∈ s, X i)

private theorem affine_coeff_unique {L : Type*} [Field L] [Algebra K L] {z : L}
    (hz : Transcendental K z) {α β α' β' : K}
    (h : algebraMap K L α * z + algebraMap K L β = algebraMap K L α' * z + algebraMap K L β') :
    α = α' ∧ β = β'

private theorem exists_prodSubgroup_val [IsAlgClosed k] [IsAlgClosed K] [UniversalDomain k K]
    {ι : Type*} [Finite ι] {v : ι → K} {g₀ : Germ k v v} (hw : g₀.IsHW) {g : Germ k v v}
    (hg : g ∈ Germ.orbit g₀) : ∃ γ : ↥hw.prodSubgroup, hw.val γ = g

private theorem indepOver_range_comp_mono {α β : Type*} {D : α → K} {σ : K → K} {M : Set K}
    (h : IndepOver k ∅ (range (σ ∘ D)) M) (f : β → K) (hf : ∀ i, ∃ j, D j = f i) :
    IndepOver k ∅ (range (σ ∘ f)) M

private theorem indep_point_union {Y Cd F M : Set K} (hF : racl k F = racl k Cd)
    (hYC : IndepOver k ∅ Y Cd) (hjoint : IndepOver k ∅ (Cd ∪ Y) M) :
    IndepOver k ∅ Y (M ∪ F)

private theorem racl_slEntries_sqrtMat {F : Type*} [Field F] [Algebra F K] {x a b : K}
    (hx : x ≠ 0) (ha : x ^ 2 = a) :
    racl F (slEntries (sqrtMat x b hx)) = racl F ({a, b} : Set K)

private theorem racl_restrictScalars_eq {F₀ : IntermediateField k K}
    {M : IntermediateField (↥F₀) K} {X Y : Set K} (h : racl (↥M) X = racl (↥M) Y) :
    racl (↥(M.restrictScalars k)) X = racl (↥(M.restrictScalars k)) Y

theorem erk_range_eq_of_indep_of_injective {C : Set K} {n : ℕ} {t : Fin n → K}
    (hind : (rkMatroid k C).Indep (range t)) (hinj : Function.Injective t) :
    erk k C (range t) = n

theorem locusIdeal_eq_span (a : ι → K) :
    locusIdeal L a =
      Ideal.span {f | (∀ m, f.coeff m ∈ range (algebraMap L K)) ∧ aeval a f = 0}

theorem cb_baseChange (K₀ : IntermediateField k K) (hs : IsSmall k (K₀ : Set K)) {W : Set K}
    (hW : IndepOver k ∅ (K₀ : Set K) W) {ι ι' : Type*} [Finite ι] [Finite ι'] {p : ι → K}
    {t : ι' → K} (hp : range p ⊆ W) (ht : range t ⊆ W)
    (h : range p ⊆ racl k (canonicalBase (racl k (range p)) t : Set K)) :
    range p ⊆ racl (↥K₀) (canonicalBase (racl (↥K₀) (range p)) t : Set K)

theorem locusIdeal_affineLine {s s' t : K} (L : IntermediateField k K) (hs : s ∈ L)
    (hs' : s' ∈ L) (ht : Transcendental (↥L) t) :
    locusIdeal (↥L) ![t, s * t + s'] = Ideal.span {X 1 - C s * X 0 - C s'}

theorem locusIdeal_line {s s' t : K} (hind : erk k ∅ ({s, s', t} : Set K) = 3) :
    locusIdeal (↥(racl k ({s, s'} : Set K))) ![t, s * t + s'] =
      Ideal.span {X 1 - C s * X 0 - C s'}

theorem not_isConstructibleOver_range_algebraMap [Infinite k] {t : K}
    (ht : t ∉ range (algebraMap k K)) :
    ¬ IsConstructibleOver k {u : Fin 1 → K | u 0 ∈ range (algebraMap k K)}

theorem setOf_exists_natDegree_le_one_aeval_eq_zero :
    {u : Fin 1 → K | ∃ P : Polynomial k, P ≠ 0 ∧ P.natDegree ≤ 1 ∧ Polynomial.aeval (u 0) P = 0} =
      {u | u 0 ∈ range (algebraMap k K)}

theorem not_isConstructibleOver_setOf_exists_natDegree_le_one [Infinite k] {t : K}
    (ht : t ∉ range (algebraMap k K)) :
    ¬ IsConstructibleOver k {u : Fin 1 → K | ∃ P : Polynomial k, P ≠ 0 ∧ P.natDegree ≤ 1 ∧
      Polynomial.aeval (u 0) P = 0}

private theorem exists_fraction_nonzero {L : IntermediateField k K} {ι : Type*}
    (z : ι → K) {c : K} (hc : c ∈ adjoin (↥L) (range z)) :
    ∃ P Q : MvPolynomial ι L, aeval z Q ≠ 0 ∧ c = aeval z P / aeval z Q

private theorem map_iterateFrobenius_map (S : Subfield K) (a b : ℕ) :
    (S.map (iterateFrobenius K p a)).map (iterateFrobenius K p b) =
      S.map (iterateFrobenius K p (b + a))

private theorem map_closure_image (σ : K →+* K) (S : Set K) (j : ℕ) :
    (Subfield.closure (σ '' S)).map (iterateFrobenius K p j) =
      ((Subfield.closure S).map (iterateFrobenius K p j)).map σ

private theorem relfinrank_closure_pow_eq (hp : p.Prime) {C : Set K} {x : K}
    (hxp : x ∉ Subfield.closure (C ∪ {x ^ p})) :
    Subfield.relfinrank (Subfield.closure (C ∪ {x ^ p})) (Subfield.closure (C ∪ {x})) = p

theorem exists_eq_map_iterateFrobenius (hp : p.Prime) {F : Subfield K}
    (hF : Subfield.relfinrank (F.map (frobenius K p)) F = p) {E : Subfield K} {n : ℕ}
    (h₁ : F.map (iterateFrobenius K p n) ≤ E) (h₂ : E ≤ F) :
    ∃ j ≤ n, E = F.map (iterateFrobenius K p j)

theorem eq_of_map_iterateFrobenius_eq (hp : p.Prime) {F : Subfield K}
    (hF : Subfield.relfinrank (F.map (frobenius K p)) F = p) {a b : ℕ}
    (h : F.map (iterateFrobenius K p a) = F.map (iterateFrobenius K p b)) : a = b

theorem idealOf_const_unit_eq_of_minpoly_eq {L : IntermediateField k K} {x x' : K}
    (h : minpoly (↥L) x = minpoly (↥L) x') :
    idealOf (↥L) (fun _ : Unit ↦ x) = idealOf (↥L) (fun _ : Unit ↦ x')

theorem exists_quasiRational_of_mem_dclAdjoin [Finite κ] {u : ι → K} {w : κ → K}
    (hw : ∀ j, w j ∈ dclAdjoin L u) :
    ∃ f : QuasiRational (↥L) ι κ, f.IsDefinedAt u ∧ f.eval u = w

theorem comp_map_eq_of_map_eq {μ : Type*} [Finite μ] {a'' : μ → K} {g' : Germ k a' a''}
    {g : Germ k a a'} {σ : K ≃ₐ[k] K} (hg' : g'.map σ = g') (hg : g.map σ = g) :
    (Germ.comp g' g).map σ = Germ.comp g' g

theorem isInvertible_iff_mem_dclAdjoin (g : Germ k a a') {F : IntermediateField k K}
    [IsAlgClosed ↥F] (hF : IsSmall k (F : Set K)) (hcb : g.cb ≤ F) {y : ι → K}
    (hy : IsGenericOver F a y) :
    IsInvertible g ↔ ∀ i, y i ∈ dclAdjoin F (g.eval F y)

theorem isGenericOver_iff_of_idealOf_eq {M : IntermediateField k K}
    (h : idealOf k a₁ = idealOf k a) (y : ι → K) :
    IsGenericOver M a₁ y ↔ IsGenericOver M a y

private theorem racl_union_affineCoeffs {F : Set K} {n : SL(2, K)} (hn : n 1 0 = 0) :
    racl k (F ∪ {n 0 0 / n 1 1, n 0 1 / n 1 1}) =
      racl k (F ∪ range fun ij : Fin 2 × Fin 2 ↦ n ij.1 ij.2)

theorem map_eq_map_iff_parameter_eq (g : Germ k a a') {c : μ → K}
    (hc : adjoin k (range c) = g.cb) (σ τ : K ≃ₐ[k] K) :
    g.map σ = g.map τ ↔ ⇑σ ∘ c = ⇑τ ∘ c

theorem existsUnique_orbit_parameter (g : Germ k a a') {c p : μ → K}
    (hc : adjoin k (range c) = g.cb) (hp : IsGen k c p) :
    ∃! h : ↥(orbit g), ∃ σ : K ≃ₐ[k] K, ⇑σ ∘ c = p ∧ g.map σ = h.1

private theorem aeval_map_botEquiv (u : μ → K)
    (P : MvPolynomial μ (↥(⊥ : IntermediateField k K))) :
    aeval u (MvPolynomial.map (botEquiv k K).toRingHom P) = aeval u P

theorem IsInverse.comp {μ : Type*} [Finite μ] {a'' : μ → K} {h : Germ k a' a}
    {g : Germ k a a'} {h' : Germ k a'' a'} {g' : Germ k a' a''} (hi : IsInverse h g)
    (hi' : IsInverse h' g') : IsInverse (Germ.comp h h') (Germ.comp g' g)

private theorem mk_eq_translation (hx₀ : x₀ ∉ racl k (∅ : Set K))
    {r : Representative k K ![x₀] ![x₀]} {c : K}
    (h : ∀ y, IsGenericOver (racl k ((r.M : Set K) ∪ (racl k ({c} : Set K) : Set K))) ![x₀] y →
      r.f.eval y = fun _ ↦ y 0 + c) :
    (⟦r⟧ : Germ k ![x₀] ![x₀]) = translation hx₀ c

theorem evalGen_translation (hx₀ : x₀ ∉ racl k (∅ : Set K)) (c : K) {y : Fin 1 → K}
    (hy : IsGen k ![x₀] y) (hind : IndepOver k ∅ (range y) ({c} : Set K)) :
    (translation hx₀ c).evalGen y = fun _ ↦ y 0 + c

theorem orbit_translation (hx₀ : x₀ ∉ racl k (∅ : Set K)) {c₀ : K}
    (hc₀ : c₀ ∉ racl k (∅ : Set K)) :
    orbit (translation hx₀ c₀) = translation hx₀ '' {c | c ∉ racl k (∅ : Set K)}

theorem translation_mem_orbit (hx₀ : x₀ ∉ racl k (∅ : Set K)) {c₀ : K}
    (hc₀ : c₀ ∉ racl k (∅ : Set K)) {c : K} (hc : c ∉ racl k (∅ : Set K)) :
    translation hx₀ c ∈ orbit (translation hx₀ c₀)

theorem isHW_translation (hx₀ : x₀ ∉ racl k (∅ : Set K)) {c₀ : K}
    (hc₀ : c₀ ∉ racl k (∅ : Set K)) : IsHW (translation hx₀ c₀) where
  isUnit

theorem prodSet_translation (hx₀ : x₀ ∉ racl k (∅ : Set K)) {c₀ : K}
    (hc₀ : c₀ ∉ racl k (∅ : Set K)) :
    IsHW.prodSet (translation hx₀ c₀) = range (translation hx₀)

theorem translationParam_eq (hx₀ : x₀ ∉ racl k (∅ : Set K)) (hc₀ : c₀ ∉ racl k (∅ : Set K))
    {γ : Germ k ![x₀] ![x₀]} (hγ : γ ∈ IsHW.prodSet (translation hx₀ c₀)) {a : K}
    (h : γ = translation hx₀ a) : translationParam hx₀ hc₀ hγ = a

private theorem evalGen_mul_translation (hx₀ : x₀ ∉ racl k (∅ : Set K)) {a c : K}
    {y : Fin 1 → K} (hy : IsGen k ![x₀] y) (hc : c ∉ racl k (({a} : Set K) ∪ range y)) :
    (translation hx₀ c * translation hx₀ a).evalGen y = fun _ ↦ y 0 + (c + a)

theorem erk_graphPoint [Finite ι] (r : Representative k K a a') {N : IntermediateField k K}
    (hMN : r.M ≤ N) {y : ι → K} (hy : IsGenericOver N a y) :
    erk k (N : Set K) (range (r.graphPoint y)) = erk k ∅ (range a)

theorem erk_cb_comp_eq_of_isInverse (C : Set K) {g : Germ k a a'} {h : Germ k a' a}
    (hi : IsInverse h g) (g' : Germ k a' a'') :
    erk k (C ∪ g.cb) ((Germ.comp g' g).cb : Set K) = erk k (C ∪ g.cb) (g'.cb : Set K)

theorem erk_cb_comp_eq_of_isInverse_left (C : Set K) (g : Germ k a a') {g' : Germ k a' a''}
    {h' : Germ k a'' a'} (hi : IsInverse h' g') :
    erk k (C ∪ g'.cb) ((Germ.comp g' g).cb : Set K) = erk k (C ∪ g'.cb) (g.cb : Set K)

theorem map_idealOf_le_of_inLocus (M : IntermediateField k K) {a y : ι → K}
    (h : InLocus (k := k) a y) :
    (idealOf k a).map (MvPolynomial.map (algebraMap k ↥M)) ≤ idealOf (↥M) y

theorem aeval_eq_zero_of_isGenericOver {M : IntermediateField k K} {a y x : ι → K}
    (hy : IsGenericOver M a y) (hx : InLocus (k := k) a x) {P : MvPolynomial ι M}
    (hP : aeval y P = 0) : aeval x P = 0

theorem inLocus_polynomial_image {κ : Type*} {M : IntermediateField k K} {a x : ι → K}
    (ha : IsGenericOver M a a) (hx : InLocus (k := k) a x) (p : κ → MvPolynomial ι M) :
    InLocus (k := k) (fun j ↦ aeval a (p j)) (fun j ↦ aeval x (p j))

theorem erk_le_of_idealOf_le (M : IntermediateField k K) [Finite ι] {a b : ι → K}
    (hle : idealOf (↥M) a ≤ idealOf (↥M) b) :
    erk k (M : Set K) (range b) ≤ erk k (M : Set K) (range a)

theorem erk_union_eq_of_subset_racl_of_isGenericOver {M : IntermediateField k K} {a y : ι → K}
    (hy : IsGenericOver M a y) {Z : Set K} (hZ : Z ⊆ racl k ((M : Set K) ∪ range y)) :
    erk k (M : Set K) (range y ∪ Z) = erk k ∅ (range a)

theorem idealFod_eq_fod_of_span {I : Ideal (MvPolynomial ι K)} {d : ℕ}
    (hd : Ideal.span {f | f ∈ I ∧ f.totalDegree ≤ d} = I) :
    idealFod I = fod (degSubspace I d)

theorem eq_of_codeVec_graphIdeal_eq {D : ℕ} {g g' : Germ k a a'}
    (hg : genDeg g.graphIdeal ≤ D) (hg' : genDeg g'.graphIdeal ≤ D)
    (h : codeVec D g.graphIdeal = codeVec D g'.graphIdeal) : g = g'

private theorem coefficientDerivative_coeff {ι : Type*} (D : Derivation k C C)
    (p : MvPolynomial ι C) (m : ι →₀ ℕ) :
    (coefficientDerivative D p).coeff m = D (p.coeff m)

private theorem coefficientDerivative_add {ι : Type*} (D : Derivation k C C)
    (p q : MvPolynomial ι C) :
    coefficientDerivative D (p + q) = coefficientDerivative D p + coefficientDerivative D q

private theorem coefficientDerivative_mul_X {ι : Type*} (D : Derivation k C C)
    (p : MvPolynomial ι C) (i : ι) :
    coefficientDerivative D (p * X i) = coefficientDerivative D p * X i

theorem indepOver_of_cb_le {κ : Type*} [Finite κ] {a' : κ → K} {g h : Germ k a a'}
    (hle : h.cb ≤ racl k (g.cb : Set K)) {w : Set K} (hg : IndepOver k ∅ (g.cb : Set K) w) :
    IndepOver k ∅ (h.cb : Set K) w

theorem IsInverse.evalGen_evalGen {κ : Type*} [Finite κ] {a' : κ → K} {h' : Germ k a' a}
    {h : Germ k a a'} (hi : IsInverse h' h) {y : ι → K} (hy : IsGen k a y)
    (hind : IndepOver k ∅ (range y) (h.cb : Set K)) : h'.evalGen (h.evalGen y) = y

theorem keyrank {γ h : Germ k a a} (hγ : γ ∈ prodSet g₀) (hh : h ∈ orbit g₀) {w : Set K}
    (hind : IndepOver k ∅ (h.cb : Set K) ((γ.cb : Set K) ∪ w)) :
    h * γ ∈ orbit g₀ ∧ IndepOver k ∅ ((h * γ).cb : Set K) w

theorem isGraphGeneric_graphPoint (r : Representative k K a a') {y : ι → K}
    (hy : IsGenericOver r.M a y) :
    IsGraphGeneric (⟦r⟧ : Germ k a a') r.M (r.graphPoint y)

theorem IsGraphGeneric.eq_graphPoint {r : Representative k K a a'} {F : IntermediateField k K}
    [IsAlgClosed (↥F)] (hF : IsSmall k (F : Set K)) (hFM : F ≤ r.M) {y : ι → K} {z : κ → K}
    (hind : IndepOver k (F : Set K) (range y ∪ range z) (r.M : Set K))
    (h : IsGraphGeneric (⟦r⟧ : Germ k a a') F (Sum.elim y z)) : z = r.f.eval y

theorem IsGraphGeneric.eq_eval {g : Germ k a a'} {F : IntermediateField k K} [IsAlgClosed (↥F)]
    (hF : IsSmall k (F : Set K)) (hcb : g.cb ≤ F) {y : ι → K} {z : κ → K}
    (h : g.IsGraphGeneric F (Sum.elim y z)) : z = g.eval F y

theorem IsGraphGeneric.map {g : Germ k a a'} {F : IntermediateField k K} {w : (ι ⊕ κ) → K}
    (σ : K ≃ₐ[k] K) (h : g.IsGraphGeneric F w) :
    (g.map σ).IsGraphGeneric (F.map σ.toAlgHom) (⇑σ ∘ w)

theorem eval_map (g : Germ k a a') (σ : K ≃ₐ[k] K) {F : IntermediateField k K}
    [IsAlgClosed (↥F)] (hF : IsSmall k (F : Set K)) (hcb : g.cb ≤ F) {y : ι → K}
    (hy : IsGenericOver F a y) :
    (g.map σ).eval (F.map σ.toAlgHom) (⇑σ ∘ y) = ⇑σ ∘ g.eval F y

theorem eq_of_eval_eq {g g' : Germ k a a'} {F : IntermediateField k K} [IsAlgClosed (↥F)]
    (hF : IsSmall k (F : Set K)) (hcb : g.cb ≤ F) (hcb' : g'.cb ≤ F) {y : ι → K}
    (hy : IsGenericOver F a y) (h : g.eval F y = g'.eval F y) : g = g'

theorem comp_eval (r' : Representative k K a' a'') (r : Representative k K a a') {y : ι → K}
    (hy : IsGenericOver (joinField r' r) a y) :
    (r'.comp r).f.eval y = r'.f.eval (r.f.eval y)

theorem comp_equivalent {r₁ r₂ : Representative k K a a'} {r₁' r₂' : Representative k K a' a''}
    (h : r₁.Equivalent r₂) (h' : r₁'.Equivalent r₂') :
    (r₁'.comp r₁).Equivalent (r₂'.comp r₂)

