private theorem exists_cb_derivations' (g : Germ k v v)
    (hr : 2 ≤ erk k ∅ (g.cb : Set K)) :
    ∃ D : Fin 2 → Derivation k g.cb g.cb, LinearIndependent g.cb D

private theorem exists_faithful_coefficient_variation' {g₀ : Germ k v v}
    (hw : Germ.IsHW g₀) (hv : erk k ∅ (range v) = 1) {γ : Germ k v v}
    (hγ : γ ∈ Germ.IsHW.prodSet g₀) :
    ∃ g : FractionRing (γ.cb ⊗[k] BaseFunctionField k v) ≃ₐ[γ.cb]
        FractionRing (γ.cb ⊗[k] BaseFunctionField k v),
      Function.Injective (coefficientVariationLinear (k := k) g)

private theorem exists_fresh_rational_representative {γ : Germ k v v} (hγ : γ ∈ prodSet g₀)
    {M : IntermediateField k K} (hM : IsSmall k (M : Set K)) {y : ι → K}
    (hy : IsGenericOver (racl k ((M : Set K) ∪ (γ.cb : Set K))) v y) :
    ∃ (r : Representative k K v v) (N : IntermediateField k K), (⟦r⟧ : Germ k v v) = γ ∧
      r.f.e = 0 ∧ IsAlgClosed ↥N ∧ IsSmall k (N : Set K) ∧ M ≤ N ∧ r.M ≤ N ∧
      IsGenericOver N v y

private theorem hasValue_mem_racl {M : IntermediateField k K} {y : ι → K}
    {u : LocusFunctionField k v} {x : K} (hx : HasValue M y u x) :
