    (r.f.map (inclBase r.M N h)).IsDefinedAt u ↔ r.f.IsDefinedAt u

theorem eval_map_inclBase (r : Representative (↥K₀) K a a') {N : IntermediateField (↥K₁) K}
    (h : (r.M : Set K) ⊆ N) (u : ι → K) :
