theorem exists_of_mem_diffSet_baseChange_transport {f₀ : Germ (↥K₀) a a'}
    (hf₀ : IsInvertible f₀) (h₀ : IndepOver (↥K₀) ∅ (f₀.cb : Set K) (K₁ : Set K))
    {δ : Germ (↥K₁) a₁ a₁}
    (hδ : δ ∈ diffSet ((f₀.transport h h').baseChange K₀ K₁ h₀₁ hK₁ ha ha')) :
