theorem isGerm_mapParams_iff {Q : Type u₄} (e : P → Q) {κ : Type v} {b : κ → K}
    (w : Word k P a b) (u : Q → K) (g : Germ k a b) :
    (w.mapParams e).IsGerm u g ↔ w.IsGerm (u ∘ e) g

theorem isInvertiblyAdmissible_mapParams_iff {Q : Type u₄} (e : P → Q) {κ : Type v}
    {b : κ → K} (w : Word k P a b) (u : Q → K) :
    (w.mapParams e).IsInvertiblyAdmissible u ↔ w.IsInvertiblyAdmissible (u ∘ e)

theorem hasSamples_iff {L : IntermediateField k K} {κ : Type v} {b : κ → K}
    (w : Word k P a b) :
    w.HasSamples L ↔ ∀ r ∈ w.sampleReqs, HasGenericSamples L r.2.1 r.2.2

theorem IsConstructibleOver.preimage_polynomial {κ : Type*}
    (q : κ → MvPolynomial ι k) {s : Set (κ → K)}
    (hs : IsConstructibleOver k s) :
    IsConstructibleOver k ((fun x i ↦ MvPolynomial.aeval x (q i)) ⁻¹' s)

theorem IsConstructibleOver.of_le_intermediateField
    {E E' : IntermediateField k K} (h : E ≤ E') {X : Type*} {s : Set (X → K)}
