    {φ : (ι → K) → (κ → K) → Prop}
    (hφ : IsConstructibleOver k {z : (ι ⊕ κ) → K | φ (z ∘ Sum.inl) (z ∘ Sum.inr)}) :
    IsConstructibleOver k {x : ι → K | ∃ y, φ x y}

theorem IsConstructibleOver.forall [Finite ι] {κ : Type*} [Finite κ] [IsAlgClosed K]
    {φ : (ι → K) → (κ → K) → Prop}
    (hφ : IsConstructibleOver k {z : (ι ⊕ κ) → K | φ (z ∘ Sum.inl) (z ∘ Sum.inr)}) :
    IsConstructibleOver k {x : ι → K | ∀ y, φ x y}

theorem isConstructibleOver_graph [Finite κ] (f : QuasiRational L ι κ) :
    IsConstructibleOver L {z : (ι ⊕ κ) → K |
      f.IsDefinedAt (z ∘ Sum.inl) ∧ f.eval (z ∘ Sum.inl) = z ∘ Sum.inr}

private theorem aeval_specializeMap (u : μ → K) (y : ι → K)
