private theorem slAct_mul {K : Type*} [Field K] (m₁ : SpecialLinearGroup (Fin 2) K)
    {m₂ : SpecialLinearGroup (Fin 2) K} (h₂ : m₂ 1 0 = 0) (z : K) :
    slAct (m₁ * m₂) z = slAct m₁ (slAct m₂ z)

