    racl k (S ∪ U) = racl k (T ∪ U)

theorem exists_output [IsAlgClosed Ω] {a b : Fin 2 → Ω}
    (hab : AlgebraicIndependent k (rankTwoPairTuple a b)) :
    ∃ c : Fin 2 → Ω, M.IsRealization a b c

theorem exists_right [IsAlgClosed Ω] {a c : Fin 2 → Ω}
    (hac : AlgebraicIndependent k (rankTwoPairTuple a c)) :
    ∃ b : Fin 2 → Ω, M.IsRealization a b c

theorem exists_left [IsAlgClosed Ω] {b c : Fin 2 → Ω}
    (hbc : AlgebraicIndependent k (rankTwoPairTuple b c)) :
    ∃ a : Fin 2 → Ω, M.IsRealization a b c

@[ext] theorem ext {e e' : ExtensionEquiv h h'}
    (hbase : e.baseEquiv = e'.baseEquiv)
    (htotal : e.totalEquiv = e'.totalEquiv) : e = e'

@[ext] theorem ext {e e' : NormalExtensionEquiv h h'}
    (hext : e.toExtensionEquiv = e'.toExtensionEquiv)
    (hnormal : e.normalEquiv = e'.normalEquiv) : e = e'

theorem chainOverLeft_eq_adjoin_target
    (Q : FiniteCorrespondencePair k Ω) :
    P.chainOverLeft Q = adjoin (↥P.branchField) {Q.target}

theorem chainOverRight_eq_adjoin_source
    (Q : FiniteCorrespondencePair k Ω) (h : P.target = Q.source) :
    P.chainOverRight Q h = adjoin (↥Q.branchField) {P.source}

theorem familyOverParameterSource_eq_adjoin_target :
    F.familyOverParameterSource =
      adjoin (↥F.parameterSourceField) {F.target}

theorem over_hom_ext_of_points {X Y : Over (Spec (.of k))}
    [IsReduced X.left] [LocallyOfFiniteType X.hom] [IsSeparated Y.hom] [LocallyOfFiniteType Y.hom]
    {f g : X ⟶ Y} (h : ∀ p : 𝟙_ (Over (Spec (.of k))) ⟶ X, p ≫ f = p ≫ g) : f = g

private theorem eq_cochar_of_mul_eq_one {G : Type*} [CommGroup G] {a b p q : ℤ}
    (hab : a * p + b * q = 1) {u v : G} (h : u ^ a * v ^ b = 1) :
    (u ^ q * v ^ (-p)) ^ b = u ∧ (u ^ q * v ^ (-p)) ^ (-a) = v

@[simp] theorem relocatedCompositeEquiv_refl {v : Fin 6 → K}
    (hv : idealOf k v = idealOf k (configurationReps f)) :
    relocatedCompositeEquiv hv hv = AlgEquiv.refl

@[simp] theorem relocatedConfigurationEquiv_refl {v : Fin 6 → K}
    (hv : idealOf k v = idealOf k (configurationReps f)) :
    relocatedConfigurationEquiv hv hv = AlgEquiv.refl

theorem idealOf_eq_of_aeval_iff {a b : ι → Ω}
    (H : ∀ f : MvPolynomial ι k, aeval a f = 0 ↔ aeval b f = 0) :
    idealOf k a = idealOf k b

theorem aeval_eq_aeval_of_idealOf_eq {a b : ι → Ω}
    (h : idealOf k a = idealOf k b) {f g : MvPolynomial ι k}
    (hfg : aeval a f = aeval a g) : aeval b f = aeval b g

theorem mem_racl_image_of_idealOf_eq {a b : ι → Ω}
    (h : idealOf k a = idealOf k b) {J : Set ι} {i : ι}
    (ha : a i ∈ racl k (a '' J)) : b i ∈ racl k (b '' J)

theorem notMem_racl_image_of_idealOf_eq {a b : ι → Ω}
    (h : idealOf k a = idealOf k b) {J : Set ι} {i : ι}
    (ha : a i ∉ racl k (a '' J)) : b i ∉ racl k (b '' J)

theorem transcendental_of_idealOf_eq {a b : ι → Ω}
    (h : idealOf k a = idealOf k b) {j : ι}
    (ha : Transcendental k (a j)) : Transcendental k (b j)

theorem exists_sub_C_mem_of_pow_sub_one_mem [IsAlgClosed k] {σ : Type*}
    {J : Ideal (MvPolynomial σ k)} (hJ : J.IsPrime) (M : MvPolynomial σ k) {n : ℕ}
    (hn : n ≠ 0) (hM : M ^ n - 1 ∈ J) : ∃ ζ : k, M - C ζ ∈ J

theorem two_le_ringKrullDim_quotient {R : Type*} [CommRing R] {P p₁ p₂ : Ideal R}
    [P.IsPrime] [p₁.IsPrime] [p₂.IsPrime] (h₁ : P < p₁) (h₂ : p₁ < p₂) :
    (2 : WithBot ℕ∞) ≤ ringKrullDim (R ⧸ P)

theorem idealOf_swap_span {u v : Ω} {F : MvPolynomial (Fin 2) k}
    (h : idealOf k ![u, v] = Ideal.span {F}) :
    idealOf k ![v, u] = Ideal.span {rename (Equiv.swap (0 : Fin 2) 1) F}

theorem cosetBinomial_prime [IsAlgClosed K] {c : K} (hc : c ≠ 0) {m n : ℕ}
    (hm : m ≠ 0) (hn : n ≠ 0) (hcop : Nat.gcd m n = 1) :
    Prime (cosetBinomial c m n)

private theorem multiplier_tuple_independent {a b x c : K}
    (hind : AlgebraicIndependent k ![a, b, x, c]) :
    AlgebraicIndependent k ![a, b, a * c, x]

private theorem notMem_racl_singleton_of_notMem {S : Set K} {w a' : K}
    (hwS : w ∈ racl k S) (hw0 : w ∉ racl k (∅ : Set K)) (ha' : a' ∉ racl k S) :
    w ∉ racl k ({a'} : Set K)

private theorem finite_stable_under_mul_eq_zero {S : Set K} {lam μ : K}
    (hS : S.Finite) (hlam : Transcendental k lam)
    (hstable : ∀ z ∈ S, z * lam ∈ S) (hμ : μ ∈ S) : μ = 0

theorem inverseNormalized_mem (t : F) {x : F}
    (hx : IsIntegral (parameterRing (k := k) t⁻¹) x) :
    IsIntegral (overlapRing (k := k) t) x
